// AI Page Translator - Content Script Bundle (Classic IIFE for Chrome MV3)
// Auto-generated by scripts/build-content.js. Do not edit directly.

(() => {
  'use strict';

  // ==========================================
  // Module: detector.js
  // ==========================================
  function calculateDensityScore(textLength, tagCount, paragraphCount) {
    if (textLength < 100 || paragraphCount < 1) return 0;
    return (textLength / Math.max(tagCount, 1)) * Math.sqrt(paragraphCount);
  }
  
  function findMainContent(doc = (typeof document !== 'undefined' ? document : null)) {
    if (!doc) return null;
  
    // Step 1: Explicit semantic tags
    // Do not select a single <article> if the page has 3 or more articles (feed/list page)
    const articleCount = doc.querySelectorAll ? doc.querySelectorAll('article').length : 0;
    const semanticSelector = articleCount >= 3 ? 'main, [role="main"]' : 'main, [role="main"], article';
    const semanticMain = doc.querySelector ? doc.querySelector(semanticSelector) : null;
    if (semanticMain && (semanticMain.innerText || '').trim().length > 300) {
      return semanticMain;
    }
  
    // Step 2: Feed / Article list detection
    const feedSelector = 'article, .post, .card, .feed-item, .article-item';
    const feedItems = doc.querySelectorAll ? doc.querySelectorAll(feedSelector) : [];
    if (feedItems && feedItems.length >= 3) {
      let parent = feedItems[0].parentElement;
      while (parent && parent !== doc.body) {
        const containedCount = parent.querySelectorAll ? parent.querySelectorAll(feedSelector).length : 0;
        if (containedCount >= feedItems.length) {
          return parent;
        }
        if (containedCount >= 3) {
          // Traverse up if an ancestor contains more feed items up to doc.body
          if (parent.parentElement && parent.parentElement !== doc.body) {
            const parentCount = parent.parentElement.querySelectorAll ? parent.parentElement.querySelectorAll(feedSelector).length : 0;
            if (parentCount > containedCount) {
              parent = parent.parentElement;
              continue;
            }
          }
          return parent;
        }
        parent = parent.parentElement;
      }
      if (parent && parent !== doc.body) return parent;
    }
  
    // Step 3: Density heuristic fallback
    const candidates = doc.querySelectorAll ? doc.querySelectorAll('div, section') : [];
    const blacklist = new Set(['HEADER', 'NAV', 'FOOTER', 'ASIDE', 'FORM', 'SCRIPT', 'STYLE']);
  
    let bestElement = doc.body;
    let bestScore = 0;
  
    for (const el of candidates) {
      if (blacklist.has(el.tagName)) continue;
      if (el.closest && el.closest('header, nav, footer, aside, .sidebar, .menu, .comments')) continue;
  
      const text = (el.innerText || '').trim();
      const tagCount = el.getElementsByTagName ? el.getElementsByTagName('*').length : 0;
      const pCount = el.querySelectorAll ? el.querySelectorAll('p, h1, h2, h3, h4, h5, h6, li').length : 0;
  
      const score = calculateDensityScore(text.length, tagCount, pCount);
      if (score > bestScore) {
        bestScore = score;
        bestElement = el;
      }
    }
  
    return bestElement;
  }

  // ==========================================
  // Module: walker.js
  // ==========================================
  function collectTextElements(root) {
    if (!root || !root.querySelectorAll) return [];
  
    const targetSelector = 'p, h1, h2, h3, h4, h5, h6, li, blockquote, figcaption';
    const targets = root.querySelectorAll(targetSelector);
    const validElements = [];
  
    for (const el of targets) {
      // Skip if inside code blocks, already translated, or nested in translated blocks
      if (el.closest && el.closest('pre, code, noscript, style, script, .ai-translated-block')) continue;
      if (el.dataset && el.dataset.aiOriginalHtml) continue;
  
      // Skip container elements that contain child target elements (avoid double-translating outer containers)
      if (el.querySelector && el.querySelector(targetSelector)) continue;
  
      const text = (el.innerText || '').trim();
      if (text.length < 2) continue;
  
      // Cache original text & HTML
      if (!el.dataset) {
        el.dataset = {};
      }
      if (!el.dataset.aiOriginalText) {
        el.dataset.aiOriginalText = el.innerText;
      }
      if (!el.dataset.aiOriginalHtml) {
        el.dataset.aiOriginalHtml = el.innerHTML || el.innerText;
      }
  
      validElements.push(el);
    }
  
    return validElements;
  }

  // ==========================================
  // Module: replacer.js
  // ==========================================
  function replaceTextBatch(elements, translations) {
    const schedule = typeof requestAnimationFrame === 'function' ? requestAnimationFrame : (fn) => fn();
    schedule(() => {
      elements.forEach((el, idx) => {
        const translated = translations[idx];
        if (typeof translated === 'string' && translated.trim()) {
          el.innerText = translated;
          if (el.classList && el.classList.add) {
            el.classList.add('ai-translated-block');
          }
        }
      });
    });
  }
  
  function restoreOriginalText(doc = (typeof document !== 'undefined' ? document : null)) {
    if (!doc || !doc.querySelectorAll) return;
    const elements = doc.querySelectorAll('[data-ai-original-text], [data-ai-original-html]');
    const schedule = typeof requestAnimationFrame === 'function' ? requestAnimationFrame : (fn) => fn();
    schedule(() => {
      elements.forEach(el => {
        if (el.dataset && (el.dataset.aiOriginalHtml !== undefined || el.dataset.aiOriginalText !== undefined)) {
          const restored = el.dataset.aiOriginalHtml || el.dataset.aiOriginalText;
          if (el.innerHTML !== undefined) {
            el.innerHTML = restored;
          } else {
            el.innerText = restored;
          }
          if (el.classList && el.classList.remove) {
            el.classList.remove('ai-translated-block');
          }
          delete el.dataset.aiOriginalHtml;
          delete el.dataset.aiOriginalText;
        }
      });
      if (doc.body && doc.body.dataset) {
        delete doc.body.dataset.aiPageTranslated;
      }
    });
  }

  // ==========================================
  // Module: selection.js
  // ==========================================
  async function handleSelectionTranslation(
    win = (typeof window !== 'undefined' ? window : null),
    chromeObj = (typeof chrome !== 'undefined' ? chrome : null),
    alertFn = (typeof alert !== 'undefined' ? alert : (typeof window !== 'undefined' && window.alert ? window.alert.bind(window) : null))
  ) {
    const currentWin = win || (typeof window !== 'undefined' ? window : null);
    if (!currentWin || typeof currentWin.getSelection !== 'function') return;
  
    const currentDoc = currentWin.document || (typeof document !== 'undefined' ? document : null);
    if (!currentDoc) return;
  
    const currentChrome = chromeObj || (typeof chrome !== 'undefined' ? chrome : null);
    const currentAlert = alertFn || (typeof alert !== 'undefined' ? alert : (currentWin.alert ? currentWin.alert.bind(currentWin) : () => {}));
  
    const selection = currentWin.getSelection();
    if (!selection || selection.rangeCount === 0) return;
  
    const text = selection.toString().trim();
    if (text.length < 2) return;
  
    const range = selection.getRangeAt(0);
    if (!range) return;
  
    // Create temporary highlight span
    const tempSpan = currentDoc.createElement('span');
    tempSpan.className = 'ai-translating-pulse';
    tempSpan.textContent = text;
  
    range.deleteContents();
    range.insertNode(tempSpan);
    if (typeof selection.removeAllRanges === 'function') {
      selection.removeAllRanges();
    }
  
    try {
      if (!currentChrome?.runtime?.sendMessage) {
        throw new Error('Chrome runtime messaging is not available');
      }
  
      const res = await currentChrome.runtime.sendMessage({
        type: 'TRANSLATE_SELECTION',
        payload: { text }
      });
  
      if (!res || !res.ok) {
        throw new Error(res?.error || 'Unknown error');
      }
  
      const translatedText = res.data?.translation;
      if (typeof translatedText !== 'string') {
        throw new Error('Invalid translation response');
      }
  
      // Create persistent translated span with restore on click
      const translatedSpan = currentDoc.createElement('span');
      translatedSpan.className = 'ai-translated-selection';
      translatedSpan.textContent = translatedText;
      translatedSpan.title = 'Клікніть, щоб повернути оригінал';
      if (!translatedSpan.dataset) {
        translatedSpan.dataset = {};
      }
      translatedSpan.dataset.original = text;
  
      translatedSpan.addEventListener('click', (e) => {
        if (e && typeof e.stopPropagation === 'function') {
          e.stopPropagation();
        }
        const orig = translatedSpan.dataset.original;
        translatedSpan.replaceWith(currentDoc.createTextNode(orig));
      });
  
      tempSpan.replaceWith(translatedSpan);
    } catch (err) {
      if (typeof currentAlert === 'function') {
        currentAlert(`Помилка перекладу виділеного: ${err.message}`);
      }
      tempSpan.replaceWith(currentDoc.createTextNode(text));
    }
  }

  // ==========================================
  // Module: content.js
  // ==========================================
  const BATCH_SIZE = 15;
  
  async function translateMainContent(
    progressCallback,
    doc = (typeof document !== 'undefined' ? document : null),
    chromeObj = (typeof chrome !== 'undefined' ? chrome : null)
  ) {
    const currentDoc = doc || (typeof document !== 'undefined' ? document : null);
    const currentChrome = chromeObj || (typeof chrome !== 'undefined' ? chrome : null);
  
    const root = findMainContent(currentDoc);
    const elements = collectTextElements(root);
  
    if (elements.length === 0) {
      throw new Error('Не знайдено текстових блоків для перекладу');
    }
  
    if (currentDoc?.body?.dataset) {
      currentDoc.body.dataset.aiPageTranslated = 'true';
    }
  
    for (let i = 0; i < elements.length; i += BATCH_SIZE) {
      if (currentDoc?.body?.dataset?.aiPageTranslated !== 'true') {
        return;
      }
  
      const batchElements = elements.slice(i, i + BATCH_SIZE);
      const texts = batchElements.map(el => el.innerText);
  
      if (!currentChrome?.runtime?.sendMessage) {
        throw new Error('Chrome runtime messaging is not available');
      }
  
      const res = await currentChrome.runtime.sendMessage({
        type: 'TRANSLATE_BATCH',
        payload: { texts }
      });
  
      if (currentDoc?.body?.dataset?.aiPageTranslated !== 'true') {
        return;
      }
  
      if (!res || !res.ok) {
        throw new Error(res?.error || 'Batch translation failed');
      }
  
      replaceTextBatch(batchElements, res.data.translations);
  
      if (progressCallback) {
        progressCallback(Math.min(i + BATCH_SIZE, elements.length), elements.length);
      }
    }
  }
  
  function handleContentMessage(
    message,
    sender,
    sendResponse,
    doc = (typeof document !== 'undefined' ? document : null),
    chromeObj = (typeof chrome !== 'undefined' ? chrome : null),
    win = (typeof window !== 'undefined' ? window : null)
  ) {
    const currentDoc = doc || (typeof document !== 'undefined' ? document : null);
    const currentChrome = chromeObj || (typeof chrome !== 'undefined' ? chrome : null);
    const currentWin = win || (typeof window !== 'undefined' ? window : null);
  
    if (!message) return false;
  
    if (message.action === 'TRIGGER_SELECTION_TRANSLATION') {
      handleSelectionTranslation(currentWin, currentChrome);
      sendResponse({ ok: true });
      return false;
    }
  
    if (message.action === 'GET_PAGE_STATUS') {
      const isTranslated = currentDoc?.body?.dataset?.aiPageTranslated === 'true';
      sendResponse({ ok: true, isTranslated });
      return false;
    }
  
    if (message.action === 'TRANSLATE_MAIN_CONTENT') {
      translateMainContent((done, total) => {
        if (currentChrome?.runtime?.sendMessage) {
          currentChrome.runtime.sendMessage({
            type: 'PAGE_TRANSLATION_PROGRESS',
            done,
            total
          }).catch(() => {});
        }
      }, currentDoc, currentChrome)
        .then(() => sendResponse({ ok: true }))
        .catch(err => sendResponse({ ok: false, error: err.message }));
      return true; // Keep channel open for async translation
    }
  
    if (message.action === 'RESTORE_ORIGINAL_CONTENT') {
      restoreOriginalText(currentDoc);
      sendResponse({ ok: true });
      return false;
    }
  
    return false;
  }
  
  if (typeof chrome !== 'undefined' && chrome.runtime?.onMessage) {
    chrome.runtime.onMessage.addListener(handleContentMessage);
  }
})();
